insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_12_v1'
from (values
('127.94.d.1.A',3,'A rectangular concrete slab is 20 feet long and 10 feet wide. What is its area?','["200 square feet", "60 square feet", "400 square feet", "30 square feet"]'::jsonb,0,'Area equals length times width: 20 x 10 = 200.','original'),
('127.94.d.1.A',4,'A slab 20 feet by 10 feet is poured 0.5 foot thick. What volume of concrete is needed?','["10 cubic feet", "100 cubic feet", "30 cubic feet", "200 cubic feet"]'::jsonb,1,'Volume = 20 x 10 x 0.5 = 100 cubic feet.','original'),
('127.94.d.1.B',3,'A contractor adds 10 percent extra to a 500-board order to cover waste. How many boards should be ordered?','["510", "505", "550", "600"]'::jsonb,2,'10 percent of 500 is 50; 500 + 50 = 550.','original'),
('127.94.d.1.B',4,'A decimal reading of 0.75 inch is the same as which fraction?','["5/7 inch", "1/4 inch", "7/5 inch", "3/4 inch"]'::jsonb,3,'0.75 = 75/100 = 3/4.','original'),
('127.94.d.1.C',3,'A roof rises 4 feet for every 12 feet of run. The ratio of rise to run is:','["1:3", "12:4 reversed to 1:12", "4:1", "3:1"]'::jsonb,0,'4 to 12 simplifies to 1 to 3.','original'),
('127.94.d.1.C',4,'If 2 bags of mortar mix cover 30 square feet of block, how many bags cover 90 square feet?','["4", "6", "9", "3"]'::jsonb,1,'90 is three times 30, so 2 x 3 = 6 bags.','original'),
('127.94.d.1.D',3,'A board is 8 feet 6 inches long. A cut removes 2 feet 3 inches. What length remains?','["6 feet 9 inches", "5 feet 9 inches", "6 feet 3 inches", "10 feet 9 inches"]'::jsonb,2,'8''6'''' minus 2''3'''' equals 6''3''''.','original'),
('127.94.d.1.D',4,'A 96-inch board is cut into equal pieces of 12 inches. How many pieces result?','["12", "6", "9", "8"]'::jsonb,3,'96 divided by 12 equals 8.','original'),
('127.94.d.1.E',3,'A wall is 40 feet long and 8 feet tall. Studs are 16 inches on center. About how many studs run along the wall?','["31 studs (40 x 12 / 16 = 30, plus 1)", "60 studs", "8 studs", "15 studs"]'::jsonb,0,'480 inches / 16 = 30 spaces, so 31 studs.','original'),
('127.94.d.1.E',4,'A room is 12 feet by 15 feet. Flooring costs $3 per square foot. What is the material cost?','["$270", "$540", "$90", "$180"]'::jsonb,1,'12 x 15 = 180 sq ft; 180 x 3 = 540.','original'),
('127.94.d.2.A',3,'A load that does not move, such as the weight of a roof, is a:','["Wind gust", "Vibration load", "Static load", "Live load that moves"]'::jsonb,2,'Static loads stay in place; dynamic loads change.','original'),
('127.94.d.2.A',4,'Loads from furniture and people moving in a building are called:','["Fixed loads only", "Seismic loads only", "Dead loads", "Live loads"]'::jsonb,3,'Live loads change with occupancy.','original'),
('127.94.d.2.B',3,'Steel resists pulling forces better than concrete because it has high:','["Tensile strength", "Brittleness", "Porosity", "Compressive weight"]'::jsonb,0,'Steel is strong in tension; concrete is strong in compression.','original'),
('127.94.d.2.B',4,'Concrete is commonly reinforced with steel bars because concrete alone is weak in:','["Hardness", "Tension", "Weight", "Compression"]'::jsonb,1,'Rebar carries tensile forces.','original'),
('127.94.d.3.A',3,'Mixing bleach with ammonia-based cleaners on a jobsite is dangerous because it can:','["Make a stronger cleaner", "Improve ventilation", "Release toxic gas", "Cool the mix"]'::jsonb,2,'Incompatible chemicals react hazardously.','original'),
('127.94.d.3.A',4,'Storing incompatible products together can cause:','["Better shelf life", "Lower costs", "Faster curing", "Dangerous reactions, fires, or toxic fumes"]'::jsonb,3,'Storage rules prevent reactions.','original'),
('127.94.d.3.B',3,'Which pair is incompatible and should be stored apart?','["Oxidizers and flammable liquids", "Water and sand", "Cement and gravel", "Nails and screws"]'::jsonb,0,'Oxidizers fuel fires.','original'),
('127.94.d.3.B',4,'A compatible substance for a given cleaner is one that:','["Corrodes the container", "Does not react harmfully when mixed", "Reacts violently", "Produces gas"]'::jsonb,1,'Compatibility means safe co-existence.','original'),
('127.94.d.3.C',3,'Concrete hardens through a chemical reaction called:','["Freezing", "Rusting", "Hydration", "Evaporation only"]'::jsonb,2,'Cement reacts with water to harden.','original'),
('127.94.d.3.C',4,'Epoxy adhesives cure when:','["They are heated to boiling", "They dry in air only", "They freeze", "A resin and a hardener react chemically"]'::jsonb,3,'Two-part epoxies cure by reaction.','original'),
('127.94.d.3.D',3,'Hot, dry, windy weather can make fresh concrete:','["Dry too fast and crack", "Gain strength instantly", "Harden slower", "Cure better"]'::jsonb,0,'Rapid water loss weakens the surface.','original'),
('127.94.d.3.D',4,'In cold weather, concrete crews often use blankets to:','["Stop hydration", "Keep the mix warm enough to cure", "Speed evaporation", "Cool it"]'::jsonb,1,'Freezing early damages concrete.','original'),
('127.94.d.4.A',3,'A foreman sends a daily progress report to the office by:','["Waiting until the project ends", "Leaving it on a wall", "Uploading it to a project app or emailing it", "Shouting across the site"]'::jsonb,2,'Technology speeds communication.','original'),
('127.94.d.4.A',4,'Using a tablet to transmit a site photo and report helps the office to:','["Lose data", "Delay decisions", "Ignore the site", "See conditions in real time"]'::jsonb,3,'Digital reports improve awareness.','original'),
('127.94.d.4.B',3,'A written estimate for a job should show:','["Materials, labor, and total cost", "Only the date", "Only a signature", "Only the logo"]'::jsonb,0,'Estimates give the cost breakdown.','original'),
('127.94.d.4.B',4,'A work order should state:','["A joke", "The task, location, and who is responsible", "Just the weather", "The crew''s lunch plans"]'::jsonb,1,'Work orders direct tasks.','original'),
('127.94.d.4.C',3,'Before using a new power saw, a worker should read the:','["Menu", "Phone book", "Operator''s manual", "Weather report"]'::jsonb,2,'Manuals list safe operation.','original'),
('127.94.d.4.C',4,'Manufacturer installation instructions for a window should be:','["Guessed", "Skipped", "Replaced by habit", "Followed exactly to protect warranty and performance"]'::jsonb,3,'Instructions ensure proper installation.','original'),
('127.94.d.4.D',3,'A daily jobsite log records:','["Work completed, weather, and delays", "Only payroll", "Only lunch orders", "Only jokes"]'::jsonb,0,'Logs document progress.','original'),
('127.94.d.4.D',4,'A clear jobsite log can help settle a dispute because it:','["Hides facts", "Shows what happened and when", "Replaces contracts", "Adds opinions"]'::jsonb,1,'Records support accountability.','original'),
('127.94.d.4.E',3,'A permit application is an example of a:','["Text meme", "Calendar color", "Required construction document", "Casual note"]'::jsonb,2,'Permits show legal approval to build.','original'),
('127.94.d.4.E',4,'A technical memo to a crew should be:','["Long and confusing", "Unsigned and undated", "Vague", "Clear, brief, and organized"]'::jsonb,3,'Good writing prevents errors.','original'),
('127.94.d.5.A',3,'After receiving instructions from a supervisor, a good practice is to:','["Repeat them back to confirm understanding", "Nod and walk away", "Ignore them", "Guess"]'::jsonb,0,'Confirming prevents mistakes.','original'),
('127.94.d.5.A',4,'When given a sketch and spoken directions, a worker should:','["Skip the sketch", "Check that both match before starting", "Pick the easier one", "Start immediately"]'::jsonb,1,'Match visual and verbal instructions.','original'),
('127.94.d.5.B',3,'If a measurement on a plan is unclear, a worker should:','["Guess", "Cut and hope", "Ask the supervisor before cutting material", "Wait until it is wrong"]'::jsonb,2,'Questions prevent waste.','original'),
('127.94.d.5.B',4,'A relevant question about instructions is:','["What''s for lunch?", "Who is your favorite singer?", "How late is the movie?", "Which grade of lumber should I use?"]'::jsonb,3,'Ask job-related details.','original'),
('127.94.d.6.A',3,'Giving verbal instructions to a helper is clearer when you:','["Use specific terms and measurements", "Speak vaguely", "Mumble", "Use slang only"]'::jsonb,0,'Specifics prevent errors.','original'),
('127.94.d.6.A',4,'When instructing a coworker to lift sheet goods, the best instruction is:','["''Just grab it''", "Clear steps with safety cautions", "No instruction", "''Whatever works''"]'::jsonb,1,'Clear steps prevent injuries.','original'),
('127.94.d.6.B',3,'Listening attentively on a jobsite means:','["Looking at your phone", "Interrupting", "Focusing and responding accurately", "Walking away"]'::jsonb,2,'Listening prevents rework.','original'),
('127.94.d.6.B',4,'A worker who hears ''cut it to 36 inches'' should:','["Cut by eye", "Ask nothing", "Guess 30", "Measure and confirm 36 inches before cutting"]'::jsonb,3,'Verify spoken measurements.','original'),
('127.94.d.7.A',3,'Positive customer relations begin with:','["Courteous, honest communication", "Rude replies", "Ignoring calls", "Making promises you can''t keep"]'::jsonb,0,'Respect builds trust.','original'),
('127.94.d.7.A',4,'When a client asks about delays, a contractor should:','["Deny delays", "Explain the cause and give an honest new timeline", "Blame others", "Avoid the client"]'::jsonb,1,'Honesty protects relationships.','original'),
('127.94.d.7.B',3,'A way to maintain good customer relations is to:','["Skip updates", "Argue", "Return calls promptly", "Never answer"]'::jsonb,2,'Responsiveness matters.','original'),
('127.94.d.7.B',4,'Sending a weekly progress update to a homeowner helps to:','["Hide problems", "Delay payment", "Create confusion", "Keep expectations aligned"]'::jsonb,3,'Updates maintain trust.','original'),
('127.94.d.7.C',3,'Customer satisfaction means the client:','["Feels the work met their expectations", "Is angry", "Is silent", "Is confused"]'::jsonb,0,'Satisfaction compares results to expectations.','original'),
('127.94.d.7.C',4,'A satisfied client is most likely to:','["Switch builders", "Recommend the contractor to others", "Avoid payment", "Complain"]'::jsonb,1,'Referrals follow satisfaction.','original'),
('127.94.d.7.D',3,'A contractor can measure customer satisfaction by:','["Guessing", "Ignoring comments", "Asking for feedback after the job", "Avoiding follow-up"]'::jsonb,2,'Feedback shows how well you did.','original'),
('127.94.d.7.D',4,'Reviewing survey results from past clients helps a builder to:','["Reduce communication", "Hide problems", "Raise prices only", "Improve service and quality"]'::jsonb,3,'Evaluation drives improvement.','original'),
('127.94.d.8.A',3,'Initiating a construction project includes:','["Defining goals and identifying needed resources", "Starting demolition", "Closing out", "Ignoring costs"]'::jsonb,0,'Initiation sets scope and resources.','original'),
('127.94.d.8.A',4,'Before breaking ground, a project manager should identify the:','["Crew''s hobbies", "Scope, budget, and team", "Paint colors only", "Parking rules only"]'::jsonb,1,'Initial planning guides the work.','original'),
('127.94.d.8.B',3,'Planning a project includes estimating:','["Only profit", "Weather only", "Required materials, labor, and time", "Only the date"]'::jsonb,2,'Planning drives scheduling.','original'),
('127.94.d.8.B',4,'Making a schedule that lists tasks in order helps to:','["Raise costs", "Create confusion", "Skip steps", "Coordinate trades and avoid conflicts"]'::jsonb,3,'Sequencing prevents delays.','original'),
('127.94.d.8.C',3,'When a client suggests a change, the manager should evaluate its:','["Feasibility, cost, and schedule effect", "Color only", "Weather only", "Name only"]'::jsonb,0,'Changes affect cost and time.','original'),
('127.94.d.8.C',4,'A suggestion to use a material that is unavailable locally has low:','["Texture", "Feasibility", "Color", "Weight"]'::jsonb,1,'Availability affects feasibility.','original'),
('127.94.d.8.D',3,'Monitoring a project means:','["Ignoring progress", "Avoiding reports", "Tracking progress against the plan", "Hiding changes"]'::jsonb,2,'Monitoring finds deviations early.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
