('127.94.d.13.C',3,'Creating a letter from an existing form helps to:','["Keep a consistent, professional format", "Lose branding", "Make errors", "Add confusion"]'::jsonb,0,'Forms speed production.','original'),
('127.94.d.13.C',4,'A project status report should be:','["Vague", "Organized with headings and clear details", "Messy", "Unsigned"]'::jsonb,1,'Formatting improves readability.','original'),
