('127.94.d.27.B',4,'A resume with consistent fonts and headings looks:','["Professional", "Sloppy", "Unreadable", "Confusing"]'::jsonb,0,'Formatting matters.','original'),
('127.94.d.27.C',3,'Before listing someone as a reference, a job seeker should:','["List a stranger", "Ask for their permission", "Skip it", "Assume yes"]'::jsonb,1,'Courtesy is required.','original'),
